        return 1;
    }

    // Цикл для считывания строк из файла
    string line;
    while (getline(file, line)) {
        // Цикл для проверки вхождения слова в строку
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            pos++; // Увеличить позицию, чтобы не учитывать повторяющиеся слова в одной строке
            count++; // Увеличить счетчик вхождений слова
